-- Runs as a SQL task after governance. Parameters: :catalog, :run_id
USE CATALOG IDENTIFIER(:catalog);

-- Freshness: max(ingested_at) must be at most 24h old
INSERT INTO governance.contract_sla_results
SELECT :run_id, current_timestamp(), 'urn:datacontract:sales:orders', '1.0.0', 'silver.orders', 'freshness', 'freshness', '<= 24h',
       coalesce(concat(CAST(round(age_s / 3600.0, 2) AS STRING), 'h'), 'no data'),
       coalesce(age_s <= 86400, false), 'Order Management', 'orders-data-support', 'https://teams.microsoft.com/l/channel/orders-data-support'
FROM (SELECT timestampdiff(SECOND, max(ingested_at), current_timestamp()) AS age_s
      FROM silver.orders);

-- quarantine_rate_below_5_pct: At most 5% of the orders received in the last 7 days may violate the contract
INSERT INTO governance.contract_sla_results
SELECT :run_id, current_timestamp(), 'urn:datacontract:sales:orders', '1.0.0', 'silver.orders', 'quarantine_rate_below_5_pct', 'sql', 'mustBeLessThan 0.05',
       coalesce(CAST(measured AS STRING), 'null'),
       coalesce(measured < 0.05, false), 'Order Management', 'orders-data-support', 'https://teams.microsoft.com/l/channel/orders-data-support'
FROM (SELECT (
SELECT coalesce(q / nullif(q + v, 0), 0)
FROM (SELECT
  (SELECT count(*) FROM silver.orders_quarantine WHERE _ingested_at >= current_timestamp() - INTERVAL 7 DAYS) AS q,
  (SELECT count(*) FROM silver.orders WHERE ingested_at >= current_timestamp() - INTERVAL 7 DAYS) AS v)
) AS measured);

-- Fail the task (and notify the contract owner) if anything in this run breached
SELECT CASE WHEN count_if(NOT passed) > 0 THEN raise_error(concat(
         'Data contract urn:datacontract:sales:orders v1.0.0 breached: ',
         array_join(collect_list(CASE WHEN NOT passed THEN check_name END), ', '),
         '. Owner: Order Management. Contact: orders-data-support https://teams.microsoft.com/l/channel/orders-data-support')) END AS verdict
FROM governance.contract_sla_results
WHERE run_id = :run_id AND contract_id = 'urn:datacontract:sales:orders';
